/// Media error message types returned from NDK media functions.
enum media_status_t {
  /// The requested media operation completed successfully.
  AMEDIA_OK(0),

  /// This indicates required resource was not able to be allocated.
  AMEDIACODEC_ERROR_INSUFFICIENT_RESOURCE(1100),

  /// This indicates the resource manager reclaimed the media resource used by
  /// the codec. With this error, the codec must be released, as it has moved to
  /// terminal state.
  AMEDIACODEC_ERROR_RECLAIMED(1101),
  AMEDIA_ERROR_BASE(-10000),

  /// The input media data is corrupt or incomplete.
  AMEDIA_ERROR_MALFORMED(-10001),

  /// The required operation or media formats are not supported.
  AMEDIA_ERROR_UNSUPPORTED(-10002),

  /// An invalid (or already closed) object is used in the function call.
  AMEDIA_ERROR_INVALID_OBJECT(-10003),

  /// At least one of the invalid parameters is used.
  AMEDIA_ERROR_INVALID_PARAMETER(-10004),

  /// The media object is not in the right state for the required operation.
  AMEDIA_ERROR_INVALID_OPERATION(-10005),

  /// Media stream ends while processing the requested operation.
  AMEDIA_ERROR_END_OF_STREAM(-10006),

  /// An Error occurred when the Media object is carrying IO operation.
  AMEDIA_ERROR_IO(-10007),

  /// The required operation would have to be blocked (on I/O or others), but
  /// blocking is not enabled.
  AMEDIA_ERROR_WOULD_BLOCK(-10008),
  AMEDIA_DRM_ERROR_BASE(-20000),
  AMEDIA_DRM_NOT_PROVISIONED(-20001),
  AMEDIA_DRM_RESOURCE_BUSY(-20002),
  AMEDIA_DRM_DEVICE_REVOKED(-20003),
  AMEDIA_DRM_SHORT_BUFFER(-20004),
  AMEDIA_DRM_SESSION_NOT_OPENED(-20005),
  AMEDIA_DRM_TAMPER_DETECTED(-20006),
  AMEDIA_DRM_VERIFY_FAILED(-20007),
  AMEDIA_DRM_NEED_KEY(-20008),
  AMEDIA_DRM_LICENSE_EXPIRED(-20009),
  AMEDIA_IMGREADER_ERROR_BASE(-30000),

  /// There are no more image buffers to read/write image data.
  AMEDIA_IMGREADER_NO_BUFFER_AVAILABLE(-30001),

  /// The AImage object has used up the allowed maximum image buffers.
  AMEDIA_IMGREADER_MAX_IMAGES_ACQUIRED(-30002),

  /// The required image buffer could not be locked to read.
  AMEDIA_IMGREADER_CANNOT_LOCK_IMAGE(-30003),

  /// The media data or buffer could not be unlocked.
  AMEDIA_IMGREADER_CANNOT_UNLOCK_IMAGE(-30004),

  /// The media/buffer needs to be locked to perform the required operation.
  AMEDIA_IMGREADER_IMAGE_NOT_LOCKED(-30005);

  /// The called media function failed with an unknown error.
  static const AMEDIA_ERROR_UNKNOWN = AMEDIA_ERROR_BASE;

  final int value;
