enum cryptoinfo_mode_t {
  AMEDIACODECRYPTOINFO_MODE_CLEAR(0),
  AMEDIACODECRYPTOINFO_MODE_AES_CTR(1),
  AMEDIACODECRYPTOINFO_MODE_AES_WV(2),
  AMEDIACODECRYPTOINFO_MODE_AES_CBC(3);

  final int value;
  const cryptoinfo_mode_t(this.value);

  static cryptoinfo_mode_t fromValue(int value) => switch (value) {
    0 => AMEDIACODECRYPTOINFO_MODE_CLEAR,
    1 => AMEDIACODECRYPTOINFO_MODE_AES_CTR,
    2 => AMEDIACODECRYPTOINFO_MODE_AES_WV,
    3 => AMEDIACODECRYPTOINFO_MODE_AES_CBC,
    _ => throw ArgumentError('Unknown value for cryptoinfo_mode_t: $value'),
  };
}

